        cols_cells.setdefault(col,set()).update(cells)
    cov={}
    for r0,r1,c0,c1,col in boxes:
        for r in range(r0,r1+1):
            for c in range(c0,c1+1):
                cov.setdefault((r,c),[]).append(col)
    out=[[bg]*w for _ in range(h)]
    for (r,c),cols in cov.items():
        if len(cols)==1:
