        else:
            best=None;bd=10**9
            for col in cols:
                dd=min(abs(r-p[0])+abs(c-p[1]) for p in cols_cells.get(col,[]))
                if dd<bd: bd=dd; best=col
            if best is not None: out[r][c]=best
    return out
