def comps_of(g,bg):
    h,w=len(g),len(g[0]); seen=set(); out=[]
    for r in range(h):
        for c in range(w):
            if g[r][c]!=bg and (r,c) not in seen:
                col=g[r][c]; q=deque([(r,c)]); cells=[(r,c)]; seen.add((r,c))
                while q:
                    y,x=q.popleft()
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and (ny,nx) not in seen and g[ny][nx]==col:
