    H=len(g);W=len(g[0]);seen=set();out=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]!=bg and (r,c) not in seen:
                stack=[(r,c)];comp=[]
                while stack:
                    y,x=stack.pop()
                    if (y,x) in seen: continue
                    seen.add((y,x)); comp.append((y,x))
                    for dy in(-1,0,1):
