def comp_desc(A):
    H,W=len(A),len(A[0])
    seen=set(); comps=[]
    for r in range(H):
        for c in range(W):
            if A[r][c] and (r,c) not in seen:
                st=[(r,c)]; comp=[]
                while st:
                    y,x=st.pop()
                    if (y,x) in seen or not A[y][x]: continue
                    seen.add((y,x)); comp.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
